INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十七", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/876887409d392e3dbf7c3028c1ed5b981c9251c0/content/books/zizhi-tongjian/vol-293/year-0957/part-02/sources/library/jiuwudaishi-117-march-957/source.txt", "note": "《旧五代史》卷一百十七，段落 jiu-wudaishi-205deb4a7860-p002768；EPUB电子本，纸本及异文待核", "id": "741cd85e-1fa7-5490-9361-5f55a2c4be66"}, {"title": "宋史·巻一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/876887409d392e3dbf7c3028c1ed5b981c9251c0/content/books/zizhi-tongjian/vol-293/year-0957/part-02/sources/library/songshi-1-shouchun-campaign-957/source.txt", "note": "《宋史》巻一，段落 songshi-9c6e46fee832-p000515；EPUB电子本，纸本及异文待核", "id": "0fc4415c-5fb1-50c0-97c6-0ba498fefa4f"}, {"title": "新五代史·卷六十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/876887409d392e3dbf7c3028c1ed5b981c9251c0/content/books/zizhi-tongjian/vol-293/year-0957/part-02/sources/library/xinwudaishi-62-zijin-defeat/source.txt", "note": "《新五代史》卷六十二，段落 xin-wudaishi-b08f244b9241-p003152；EPUB电子本，纸本及异文待核", "id": "f9bbcb46-61ec-52b5-b878-17167c1aeb00"}, {"title": "资治通鉴·后周纪四", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a3c2b1a6cf242bf4514a4d6934756f84abb3c1ce/content/books/zizhi-tongjian/vol-293/year-0957/part-01/sources/library/tongjian-293-957-february-march/source.txt", "note": "《资治通鉴》后周纪四，段落 zizhi-tongjian-a63549944a71-p003481；电子底本待考，分段待核", "id": "d48b53b3-0246-5fbb-9456-5d402d58c83f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "舒元", "aliases": ["朱元", "硃元"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沈丘人，早先以游士身份投靠李守贞。李守贞被后汉围攻后，让他改姓朱，赴南唐求援。《新五代史》记求援者为朱元。生卒年尚未确定。", "biography": null, "status": "draft", "id": "4747ce90-dd4b-5e0b-a0c8-7420788a2347"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "杨守忠（南唐武昌节度使）", "aliases": ["楊守忠（南唐武昌節度使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐武昌节度使。957年受命代朱元领军，抵濠州，在紫金山战败被俘。与891年同名将领缺少连续履历证据，分别保存。生卒年未载。", "biography": null, "status": "draft", "id": "abb39be8-1c20-5679-ba0b-5e08568e3157"}, {"name": "徐景达", "aliases": ["景达", "徐景達"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐诰的儿子。937年十一月被封为寿阳公，姓名在本站统一使用此时的徐氏形式。具体生卒年份此段未载。", "biography": null, "status": "draft", "id": "75c1ce40-b9c2-5bfe-bdca-c73be3b25efd"}, {"name": "宋垍", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朱元的门客。957年朱元将被夺兵权、欲自杀时，他劝其另求富贵。生卒年未载。", "biography": null, "status": "draft", "id": "61bd901f-04c1-51d7-9faa-e368660deb3c"}, {"name": "朱仁裕", "aliases": ["硃仁裕"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐先锋壕寨使。957年随朱元率营寨万余人投降后周。生卒年未载。", "biography": null, "status": "draft", "id": "38536154-a139-5092-a526-981046b8109a"}, {"name": "孙璘", "aliases": ["孫璘"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。《旧五代史》记957年与朱元、朱仁裕分别率营寨降周。职衔与生卒年未载。", "biography": null, "status": "draft", "id": "6f6b57e0-8dfe-534c-863f-99524385ea7d"}, {"name": "时厚卿", "aliases": ["時厚卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。945年《资治通鉴》记他在汀州战事中被许文稹俘获。生卒年与其他履历本段未载。", "biography": null, "status": "draft", "id": "675c35b2-5856-5f79-9edb-12494aaceec5"}, {"name": "赵晁", "aliases": ["趙晁"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "真定人，后周控鹤都指挥使。954年三月向郑好谦表示宜慎重进军，郑转告柴荣后，两人被拘于怀州狱。生卒年未载。", "biography": null, "status": "draft", "id": "cd9622d4-b011-5634-b050-b6b748a36838"}, {"name": "许文稹", "aliases": ["許文稹", "许文缜", "許文縝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "同安人，汀州刺史。944年朱文进掌权后率郡投降朱文进。《新五代史》对应汀州守将作許文縝，保留姓名字形异文；该书后文投降王延政为另一阶段，不混为当前投降对象。生卒年未载。", "biography": null, "status": "draft", "id": "6717f767-1ab2-52b8-8015-c778cc06ee45"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}, {"name": "郭廷谓", "aliases": ["郭廷謂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "彭城人，南唐濠州都监。957年率水军溯淮欲烧浮桥，被赵匡赞伏兵击败。生卒年未载。", "biography": null, "status": "draft", "id": "19bb918a-ace7-5a46-9480-796bbc67a61a"}, {"name": "赵匡赞", "aliases": ["趙匡贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "赵延寿的儿子。947年正月受耶律德光任命为护国节度使。生卒年未载。", "biography": null, "status": "draft", "id": "ad59529e-c641-5bb7-bde5-3749239fd1d3"}, {"name": "陈德诚", "aliases": ["陳德誠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "静江指挥使。956年南唐潘承祐在泉建募兵时举荐，随后陆孟俊恢复泰州，派其戍守。生卒年未载。", "biography": null, "status": "draft", "id": "5c0f3a0f-e33c-5bb5-bed7-26075de15f3b"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "乔匡舜", "aliases": ["喬匡舜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐中书舍人。956年赴吴越出使，柴克宏进常州时声称船队是迎接他，以掩护登岸突袭。生卒年未载。", "biography": null, "status": "draft", "id": "9c534c02-4acf-5688-8211-5c3577943c94"}, {"name": "朱匡业", "aliases": ["硃匡業", "朱匡業"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐神卫统军。956年李征古拟让其代柴克宏，随后到达常州行营，柴克宏谨慎事奉。史书字形硃沿原文，主体用朱；生卒年未载。", "biography": null, "status": "draft", "id": "8300b93a-97ee-584f-b7f5-990378a6c507"}, {"name": "刘存忠", "aliases": ["劉存忠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。957年赞同朱匡业所诵罗隐诗的回答，被李璟流放饶州。生卒年未载。", "biography": null, "status": "draft", "id": "a7995f0e-0909-59ec-94d2-dc5138211777"}, {"name": "周廷构", "aliases": ["周廷構"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐寿州监军使。957年刘崇谏被父亲下令处死时，先哭求刘仁赡，又求其夫人相救，未获允许。生卒年未载。", "biography": null, "status": "draft", "id": "d7ac22dd-cc9c-5a26-a87e-55a75330cee8"}, {"name": "孙羽", "aliases": ["孫羽"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐寿州营田副使。957年刘仁赡病重不能认人时，与周廷构等代拟降表，派使降周。生卒年未载。", "biography": null, "status": "draft", "id": "8775a6b9-4fd2-5d5d-af26-9d9bb8f0746c"}, {"name": "张保续", "aliases": ["張保續"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周阖门使，万年人。957年奉柴荣命入寿春宣谕。《旧五代史》相同使职任务的姓名作张保绩，按姓名异文关联，纸本待核。生卒年未载。", "biography": null, "status": "draft", "id": "af8b5760-2b27-5433-a326-0acb3084e15f"}, {"name": "刘崇让", "aliases": ["劉崇讓", "崇让"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘仁赡之子。957年寿春受降时出城谢罪，与已被处死的刘崇谏分别保存。年龄与长幼次序未载。", "biography": null, "status": "draft", "id": "cd3e9f68-c007-59da-b31f-855e35a5c82b"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
